1	<!DOCTYPE html>
2	<html lang="en">
3	<head>
4	<meta charset="utf-8">
5	<meta name="viewport" content="width=device-width, initial-scale=1">
6	<title>Todos</title>
7	<style>
8	  * { box-sizing: border-box; }
9	  body { margin: 0; font: 16px/1.4 system-ui, sans-serif; background: #f6f6f4; color: #222; }
10	  main { max-width: 520px; margin: 40px auto; padding: 0 16px; }
11	  h1 { font-size: 1.6rem; margin: 0 0 16px; }
12	  form { display: flex; gap: 8px; margin-bottom: 16px; }
13	  input { flex: 1; padding: 10px; font: inherit; border: 1px solid #ccc; border-radius: 6px; }
14	  button { padding: 10px 14px; font: inherit; border: 0; border-radius: 6px; background: #2b6cb0; color: #fff; cursor: pointer; }
15	  ul { list-style: none; margin: 0; padding: 0; }
16	  li { display: flex; align-items: center; gap: 8px; padding: 10px 12px; background: #fff; border: 1px solid #e3e3e3; border-radius: 6px; margin-bottom: 8px; }
17	  li span { flex: 1; word-break: break-word; }
18	  li button { background: #c53030; padding: 6px 10px; font-size: 0.9rem; }
19	  li input[type="checkbox"] { flex: none; width: 18px; height: 18px; margin: 0; }
20	  li[data-completed="true"] span { text-decoration: line-through; color: #888; }
21	  input[type="date"] { flex: none; }
22	  li .due { flex: none; font-size: 0.85rem; color: #555; }
23	  select { flex: none; padding: 10px; font: inherit; border: 1px solid #ccc; border-radius: 6px; background: #fff; }
24	  li .priority { flex: none; font-size: 0.85rem; color: #555; }
25	  li[data-overdue="true"] { border-color: #c53030; background: #fff5f5; }
26	  li[data-overdue="true"] .due { color: #c53030; font-weight: 600; }
27	  .filters { display: flex; gap: 8px; margin-bottom: 16px; }
28	  .filters button { background: #e2e8f0; color: #222; padding: 6px 12px; font-size: 0.9rem; }
29	  .filters button[aria-pressed="true"] { background: #2b6cb0; color: #fff; }
30	</style>
31	</head>
32	<body>
33	<main>
34	  <h1>Todos</h1>
35	  <form id="todo-form">
36	    <input data-testid="todo-input" type="text" placeholder="What needs doing?" autocomplete="off" aria-label="New todo">
37	    <input data-testid="todo-due" type="date" aria-label="Due date">
38	    <select data-testid="todo-priority" aria-label="Priority">
39	      <option value="low">Low</option>
40	      <option value="med" selected>Med</option>
41	      <option value="high">High</option>
42	    </select>
43	    <button data-testid="todo-add" type="submit">Add</button>
44	  </form>
45	  <div class="filters">
46	    <button data-testid="filter-all" data-filter="all" type="button" aria-pressed="true">All</button>
47	    <button data-testid="filter-active" data-filter="active" type="button" aria-pressed="false">Active</button>
48	    <button data-testid="filter-completed" data-filter="completed" type="button" aria-pressed="false">Completed</button>
49	  </div>
50	  <ul data-testid="todo-list"></ul>
51	</main>
52	<script>
53	  var STORAGE_KEY = 'todos';
54	  var form = document.getElementById('todo-form');
55	  var input = document.querySelector('[data-testid="todo-input"]');
56	  var dueInput = document.querySelector('[data-testid="todo-due"]');
57	  var priorityInput = document.querySelector('[data-testid="todo-priority"]');
58	  var list = document.querySelector('[data-testid="todo-list"]');
59	  var filterButtons = document.querySelectorAll('[data-filter]');
60	  var todos = loadTodos();
61	  var currentFilter = 'all';
62	
63	  // [REQ-001]
64	  function loadTodos() {
65	    try {
66	      var data = JSON.parse(localStorage.getItem(STORAGE_KEY));
67	      return Array.isArray(data) ? data : [];
68	    } catch (e) {
69	      return [];
70	    }
71	  }
72	
73	  // [REQ-001]
74	  function saveTodos() {
75	    try {
76	      localStorage.setItem(STORAGE_KEY, JSON.stringify(todos));
77	    } catch (e) {}
78	  }
79	
80	  // [REQ-001]
81	  function makeId() {
82	    if (window.crypto && typeof crypto.randomUUID === 'function') return crypto.randomUUID();
83	    return Date.now().toString(36) + '-' + Math.random().toString(36).slice(2, 10);
84	  }
85	
86	  // [REQ-003] Due dates are plain local YYYY-MM-DD strings; never parsed through UTC.
87	  function normalizeDue(value) {
88	    return typeof value === 'string' && /^\d{4}-\d{2}-\d{2}$/.test(value) ? value : null;
89	  }
90	
91	  // [REQ-003] Today's LOCAL calendar date as YYYY-MM-DD.
92	  function localToday(now) {
93	    now = now || new Date();
94	    var m = String(now.getMonth() + 1).padStart(2, '0');
95	    var d = String(now.getDate()).padStart(2, '0');
96	    return now.getFullYear() + '-' + m + '-' + d;
97	  }
98	
99	  // [REQ-003] Overdue = due date strictly before today's local date (date-only string compare).
100	  function isOverdue(due, today) {
101	    return !!due && due < today;
102	  }
103	
104	  // [REQ-004] Priority is low, med or high; anything else (including missing) is med.
105	  function normalizePriority(value) {
106	    return value === 'low' || value === 'high' ? value : 'med';
107	  }
108	
109	  // [REQ-001] [REQ-003] [REQ-004]
110	  function addTodo(text, due, priority) {
111	    text = text.trim();
112	    if (!text) return;
113	    todos.push({ id: makeId(), text: text, createdAt: Date.now(), completed: false, due: normalizeDue(due), priority: normalizePriority(priority) });
114	    saveTodos();
115	    render();
116	  }
117	
118	  // [REQ-001]
119	  function deleteTodo(id) {
120	    todos = todos.filter(function (t) { return t.id !== id; });
121	    saveTodos();
122	    render();
123	  }
124	
125	  // [REQ-002]
126	  function toggleTodo(id) {
127	    todos.forEach(function (t) {
128	      if (t.id === id) t.completed = !t.completed;
129	    });
130	    saveTodos();
131	    render();
132	  }
133	
134	  // [REQ-005] Highest priority first; insertion order within the same priority. Does not mutate items.
135	  function byPriority(items) {
136	    var rank = { high: 0, med: 1, low: 2 };
137	    return items
138	      .map(function (t, i) { return { t: t, i: i }; })
139	      .sort(function (a, b) {
140	        return (rank[normalizePriority(a.t.priority)] - rank[normalizePriority(b.t.priority)]) || (a.i - b.i);
141	      })
142	      .map(function (x) { return x.t; });
143	  }
144	
145	  // [REQ-002] [REQ-005] Active todos first, then completed; by priority, then insertion order within each group.
146	  function visibleTodos(items, filter) {
147	    var active = byPriority(items.filter(function (t) { return !t.completed; }));
148	    var done = byPriority(items.filter(function (t) { return !!t.completed; }));
149	    if (filter === 'active') return active;
150	    if (filter === 'completed') return done;
151	    return active.concat(done);
152	  }
153	
154	  // [REQ-002]
155	  function setFilter(filter) {
156	    currentFilter = filter;
157	    render();
158	  }
159	
160	  // [REQ-001] [REQ-002] [REQ-003] [REQ-004] [REQ-006] Priority shown as plain text, no colour coding.
161	  function render() {
162	    var today = localToday();
163	    list.textContent = '';
164	    filterButtons.forEach(function (btn) {
165	      btn.setAttribute('aria-pressed', String(btn.dataset.filter === currentFilter));
166	    });
167	    visibleTodos(todos, currentFilter).forEach(function (todo) {
168	      var li = document.createElement('li');
169	      li.setAttribute('data-testid', 'todo-item');
170	      li.setAttribute('data-completed', String(!!todo.completed));
171	      li.setAttribute('data-overdue', String(isOverdue(normalizeDue(todo.due), today)));
172	      li.setAttribute('data-priority', normalizePriority(todo.priority));
173	      li.dataset.id = todo.id;
174	
175	      var toggle = document.createElement('input');
176	      toggle.type = 'checkbox';
177	      toggle.setAttribute('data-testid', 'todo-toggle');
178	      toggle.setAttribute('aria-label', 'Mark complete');
179	      toggle.checked = !!todo.completed;
180	      toggle.addEventListener('change', function () { toggleTodo(todo.id); });
181	
182	      var span = document.createElement('span');
183	      span.setAttribute('data-testid', 'todo-text');
184	      span.textContent = todo.text;
185	
186	      var del = document.createElement('button');
187	      del.type = 'button';
188	      del.setAttribute('data-testid', 'todo-delete');
189	      del.textContent = 'Delete';
190	      del.addEventListener('click', function () { deleteTodo(todo.id); });
191	
192	      li.appendChild(toggle);
193	      li.appendChild(span);
194	      var priority = document.createElement('span');
195	      priority.className = 'priority';
196	      priority.textContent = { high: 'High', med: 'Med', low: 'Low' }[normalizePriority(todo.priority)];
197	      li.appendChild(priority);
198	      if (normalizeDue(todo.due)) {
199	        var due = document.createElement('span');
200	        due.className = 'due';
201	        due.setAttribute('data-testid', 'todo-due-label');
202	        due.textContent = 'Due ' + todo.due;
203	        li.appendChild(due);
204	      }
205	      li.appendChild(del);
206	      list.appendChild(li);
207	    });
208	  }
209	
210	  filterButtons.forEach(function (btn) {
211	    btn.addEventListener('click', function () { setFilter(btn.dataset.filter); });
212	  });
213	
214	  form.addEventListener('submit', function (e) {
215	    e.preventDefault();
216	    addTodo(input.value, dueInput.value, priorityInput.value);
217	    input.value = '';
218	    dueInput.value = '';
219	    priorityInput.value = 'med';
220	    input.focus();
221	  });
222	
223	  render();
224	</script>
225	</body>
226	</html>
